def gen(rng):
    def fmt(n, rs):
        return f"{n} {len(rs)}\n" + "\n".join(map(str, rs))
    def rnd(n, q, hi=10**9):
        return fmt(n, [rng.randint(0, hi) for _ in range(q)])
    tests = [fmt(1, [0]), fmt(1, [5, 9, 3]), fmt(2, [0, 0, 0, 0, 1, 1]), fmt(3, [4, 0, 5, 1, 1]), fmt(4, [0, 0, 0, 0])]
    for n, q in [(2, 9), (3, 12), (5, 20), (6, 30), (7, 40), (10, 50), (13, 60), (20, 70)]:
        tests.append(rnd(n, q, 10**rng.randint(1, 9)))
    for _ in range(5):
        n = rng.randint(1, 15)
        tests.append(rnd(n, rng.randint(1, 60), 100))
    tests.append(rnd(10**6, 200000))
    tests.append(rnd(1000, 200000))
    tests.append(rnd(2, 200000))
    tests.append(rnd(450, 200000))
    tests.append(fmt(10**6, [10**9 - i for i in range(200000)]))
    return tests

